    const base = parse(match[2]);
    if (operator === '^' || operator === '~') {
      const upper = operator === '~' ? [base[0], base[1] + 1, 0]
        : base[0] !== 0 ? [base[0] + 1, 0, 0]
          : base[1] !== 0 ? [0, base[1] + 1, 0]
            : [0, 0, base[2] + 1];
